def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    if history[0][1] == 'D':
        return 'D'
    opp = [h[1] for h in history]
    my = [h[0] for h in history]
    opp_def = sum(1 for x in opp if x == 'D')
    my_c = sum(1 for x in my if x == 'C')
    if n >= 10 and opp_def / n > 0.8:
        return 'D'
    if n >= 5 and all(x == 'D' for x in opp[-5:]):
        return 'D'
    last_opp = opp[-1]
    my_coop_rate = my_c / n
    if last_opp == 'D':
        consec = 0
        for x in reversed(opp):
            if x == 'D':
                consec += 1
            else:
                break
        if my_coop_rate > 0.8:
            return 'D'
        if consec == 1:
            if rng.random() < 0.5:
                return 'C'
        elif consec == 2:
            if rng.random() < 0.25:
                return 'C'
        elif consec >= 3:
            if rng.random() < 0.1:
                return 'C'
        return 'D'
    else:
        return 'C'
